"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([["266"],{6164(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"category","label":"tutorial","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/tutorial/getting-started","label":"From an empty capacity to a loaded Silver table","docId":"tutorial/getting-started","unlisted":false}]},{"type":"link","href":"/docs/intro","label":"intro","docId":"intro","unlisted":false},{"type":"category","label":"how-to","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/how-to/deploy","label":"Deploy FMD from nothing","docId":"how-to/deploy","unlisted":false},{"type":"link","href":"/docs/how-to/add-an-entity","label":"Register a new source entity","docId":"how-to/add-an-entity","unlisted":false},{"type":"link","href":"/docs/how-to/schedule-the-load","label":"Schedule the load","docId":"how-to/schedule-the-load","unlisted":false},{"type":"link","href":"/docs/how-to/run-fmd-in-production","label":"Run FMD in production","docId":"how-to/run-fmd-in-production","unlisted":false},{"type":"link","href":"/docs/how-to/diagnose-a-failed-load","label":"Diagnose a failed load","docId":"how-to/diagnose-a-failed-load","unlisted":false},{"type":"link","href":"/docs/how-to/create-onelake-shortcuts-in-gold","label":"Create OneLake shortcuts in Gold","docId":"how-to/create-onelake-shortcuts-in-gold","unlisted":false},{"type":"link","href":"/docs/how-to/create-materialized-lake-views","label":"Create Materialized Lake Views","docId":"how-to/create-materialized-lake-views","unlisted":false},{"type":"link","href":"/docs/how-to/upgrade-the-framework","label":"Upgrade the framework","docId":"how-to/upgrade-the-framework","unlisted":false},{"type":"link","href":"/docs/how-to/operator-cheat-sheet","label":"Operator cheat sheet","docId":"how-to/operator-cheat-sheet","unlisted":false}]},{"type":"category","label":"reference","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/reference/data-model","label":"Data model reference","docId":"reference/data-model","unlisted":false},{"type":"link","href":"/docs/reference/logging-and-auditing","label":"Logging and auditing reference","docId":"reference/logging-and-auditing","unlisted":false},{"type":"link","href":"/docs/reference/pipelines","label":"Pipelines","docId":"reference/pipelines","unlisted":false},{"type":"link","href":"/docs/reference/notebooks","label":"Notebooks","docId":"reference/notebooks","unlisted":false},{"type":"link","href":"/docs/reference/data-cleansing","label":"Data cleansing","docId":"reference/data-cleansing","unlisted":false},{"type":"link","href":"/docs/reference/variable-libraries","label":"Variable libraries","docId":"reference/variable-libraries","unlisted":false},{"type":"link","href":"/docs/reference/supported-sources","label":"Supported sources","docId":"reference/supported-sources","unlisted":false},{"type":"link","href":"/docs/reference/version-differences","label":"Version differences: 2026.07 and main","docId":"reference/version-differences","unlisted":false}]},{"type":"category","label":"explanation","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/explanation/why-fmd","label":"Why FMD, and when not to use it","docId":"explanation/why-fmd","unlisted":false},{"type":"link","href":"/docs/explanation/enterprise-integration","label":"FMD in an enterprise data landscape","docId":"explanation/enterprise-integration","unlisted":false},{"type":"link","href":"/docs/explanation/architecture","label":"Architecture","docId":"explanation/architecture","unlisted":false},{"type":"link","href":"/docs/explanation/load-flow","label":"How data moves through FMD","docId":"explanation/load-flow","unlisted":false},{"type":"link","href":"/docs/explanation/business-domains","label":"Business Domains and the Gold layer","docId":"explanation/business-domains","unlisted":false}]},{"type":"link","href":"/docs/","label":"The Fabric Metadata-Driven Framework (FMD)","docId":"index","unlisted":false}]},"docs":{"explanation/architecture":{"id":"explanation/architecture","title":"Architecture","description":"Who can edit a pipeline, who can read a Silver table, and what has to be re-pointed when you promote to production are all decided by one thing in FMD: which workspace an artefact lives in.","sidebar":"tutorialSidebar"},"explanation/business-domains":{"id":"explanation/business-domains","title":"Business Domains and the Gold layer","description":"The core of FMD is one shared machine: one set of pipelines, one configuration database, one Landing Zone, one Bronze and one Silver lakehouse, described in how data moves through FMD. That machine is deliberately business-agnostic. It ingests, hashes, cleanses and historises whatever entities you register, and it has no opinion at all about what \\"a customer\\" or \\"an order\\" means.","sidebar":"tutorialSidebar"},"explanation/enterprise-integration":{"id":"explanation/enterprise-integration","title":"FMD in an enterprise data landscape","description":"FMD is one component in a platform, not a platform. This page places it: what feeds it, what consumes it, what it costs to run, what a governance review will ask of it, how it is secured, how it is promoted from development to production, and who has to get out of bed when it fails.","sidebar":"tutorialSidebar"},"explanation/load-flow":{"id":"explanation/load-flow","title":"How data moves through FMD","description":"FMD moves a source table through three physical stops: a file in the Landing Zone, a current-state Delta table in Bronze, and a historised Delta table in Silver. Nothing about that path is hard-coded per table. Every step reads its instructions from a row in the configuration database, and every step writes back to that database what it did.","sidebar":"tutorialSidebar"},"explanation/why-fmd":{"id":"explanation/why-fmd","title":"Why FMD, and when not to use it","description":"A data platform that hand-builds one pipeline per source table is buying a linear cost curve. FMD is a metadata-driven ingestion framework for Microsoft Fabric that flattens it: you describe a table as rows in a configuration database, and a fixed set of pipelines and notebooks lands it, historises it and audits it.","sidebar":"tutorialSidebar"},"how-to/add-an-entity":{"id":"how-to/add-an-entity","title":"Register a new source entity","description":"FMD loads what its metadata tells it to load. To make the framework pick up a new table or file, you do not edit a pipeline: you insert metadata into the configuration database, and the pipelines find it on their next run.","sidebar":"tutorialSidebar"},"how-to/create-materialized-lake-views":{"id":"how-to/create-materialized-lake-views","title":"Create Materialized Lake Views","description":"A Materialized Lake View (MLV) is the persisted result of a SparkSQL SELECT, stored as a table in the lakehouse and refreshed by Fabric rather than by a query at read time. In FMD it is how a Business Domain turns raw historised Silver tables into the facts and dimensions its reports actually consume.","sidebar":"tutorialSidebar"},"how-to/create-onelake-shortcuts-in-gold":{"id":"how-to/create-onelake-shortcuts-in-gold","title":"Create OneLake shortcuts in Gold","description":"A Business Domain\'s Gold lakehouse gets its data from Silver through OneLake shortcuts: references, not copies. The bytes stay in the Silver lakehouse in the core Data workspace, and the Gold lakehouse sees them as if they were its own tables.","sidebar":"tutorialSidebar"},"how-to/deploy":{"id":"how-to/deploy","title":"Deploy FMD from nothing","description":"This page takes you from an empty Fabric tenant to a running FMD Framework: three (or five) workspaces, three lakehouses per environment, a configuration SQL database, and every notebook and pipeline the framework needs.","sidebar":"tutorialSidebar"},"how-to/diagnose-a-failed-load":{"id":"how-to/diagnose-a-failed-load","title":"Diagnose a failed load","description":"Silver is empty, or stale, and nobody was paged. This page gets you from that to a named entity and a reason.","sidebar":"tutorialSidebar"},"how-to/operator-cheat-sheet":{"id":"how-to/operator-cheat-sheet","title":"Operator cheat sheet","description":"The handful of queries and rules you reach for when a load looks wrong, on one page. Everything here is condensed: the fuller reasoning is in run FMD in production and diagnose a failed load, which each link is a pointer into.","sidebar":"tutorialSidebar"},"how-to/run-fmd-in-production":{"id":"how-to/run-fmd-in-production","title":"Run FMD in production","description":"The checklist before FMD carries a real load. What to configure, what to alert on, and the places where you have to watch because the framework cannot watch for itself.","sidebar":"tutorialSidebar"},"how-to/schedule-the-load":{"id":"how-to/schedule-the-load","title":"Schedule the load","description":"FMD ships no schedule and no trigger. Not one of the 25 pipelines carries a trigger definition, and there is no schedule artefact in the repository. Until you create one, PLFMDLOAD_ALL runs when somebody presses Run.","sidebar":"tutorialSidebar"},"how-to/upgrade-the-framework":{"id":"how-to/upgrade-the-framework","title":"Upgrade the framework","description":"Re-running the setup notebook is the upgrade mechanism. There is no separate upgrade path, and there does not need to be one: the setup upserts every artefact, so running it again against an existing deployment replaces the framework\'s items and leaves your data and your metadata alone.","sidebar":"tutorialSidebar"},"index":{"id":"index","title":"The Fabric Metadata-Driven Framework (FMD)","description":"FMD is written and maintained by Erwin de Kreuk and published under the MIT licence at github.com/edkreuk/FMD_FRAMEWORK. This documentation is not his: we read his code and wrote down what it does. Where we found a defect we say so on the page, and we say which pull request fixes it. Where we were wrong, he was right.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"intro","description":"---","sidebar":"tutorialSidebar"},"reference/data-cleansing":{"id":"reference/data-cleansing","title":"Data cleansing","description":"Cleansing in FMD is a metadata-driven transformation step applied to a DataFrame in flight, between reading the source and writing the target. A rule is a JSON object stored in the configuration database against an entity; a function is a Python callable registered by name in a Spark-session-wide registry. The rule names the function, and the framework looks it up.","sidebar":"tutorialSidebar"},"reference/data-model":{"id":"reference/data-model","title":"Data model reference","description":"This database is the framework. Everything else in FMD is generic all of it is reading and writing these 14 tables.","sidebar":"tutorialSidebar"},"reference/logging-and-auditing":{"id":"reference/logging-and-auditing","title":"Logging and auditing reference","description":"Every pipeline, every copy activity and every notebook in FMD opens and closes an audit record in the configuration database. That trail is the framework\'s entire observability story: there is no semantic model, no alerting, no retention job, and nothing in FMD reads its own audit trail back.","sidebar":"tutorialSidebar"},"reference/notebooks":{"id":"reference/notebooks","title":"Notebooks","description":"Everything FMD does to your data happens in a notebook. The pipelines move bytes","sidebar":"tutorialSidebar"},"reference/pipelines":{"id":"reference/pipelines","title":"Pipelines","description":"FMD ships 25 Fabric Data Pipelines. None of them names a table, a column, or a","sidebar":"tutorialSidebar"},"reference/supported-sources":{"id":"reference/supported-sources","title":"Supported sources","description":"FMD loads from nine source families. The set is not open-ended: it is exactly the","sidebar":"tutorialSidebar"},"reference/variable-libraries":{"id":"reference/variable-libraries","title":"Variable libraries","description":"FMD keeps its environment-specific configuration in two Fabric Variable Libraries, VARFMD and VARCONFIG_FMD. Between them they hold seven variables. Nothing else in the framework is environment-dependent: workspace GUIDs, database names, and connection strings all resolve through these two libraries, which is what lets the same item definitions be deployed to Test, Acceptance, and Production unchanged.","sidebar":"tutorialSidebar"},"reference/version-differences":{"id":"reference/version-differences","title":"Version differences: 2026.07 and main","description":"This page is one place to answer a single question: does this behaviour depend on which version I deployed?","sidebar":"tutorialSidebar"},"tutorial/getting-started":{"id":"tutorial/getting-started","title":"From an empty capacity to a loaded Silver table","description":"This page was executed, not written. Every timing and every value below comes from a real deployment into a real Fabric tenant on 2026-07-13, against the framework at commit 1ba7974.","sidebar":"tutorialSidebar"}}}}')}}]);